mapper.select:
SELECT f.id, f.type, f.account_id, a.username, a.nickname, f.order_id, o.order_no, f.content, f.status, f.create_time, CASE WHEN f.reply IS NULL THEN 0 ELSE 1 END AS replied FROM feedback f LEFT JOIN account a ON a.id = f.account_id AND a.deleted = 0 LEFT JOIN orders o ON o.id = f.order_id AND o.deleted = 0 WHERE f.deleted = 0
AND f.type = #{type}
AND f.status = #{status}
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND (a.username LIKE CONCAT('%', #{username}, '%') OR a.nickname LIKE CONCAT('%', #{username}, '%'))
AND f.create_time >= #{dateFrom}
AND f.create_time < #{dateTo}
ORDER BY CASE f.status WHEN 'PENDING' THEN 0 WHEN 'PROCESSING' THEN 1 WHEN 'REPLIED' THEN 2 ELSE 3 END, f.create_time DESC, f.id DESC
